import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        System.out.print("Enter age: ");
        int age = scanner.nextInt();

        System.out.print("Enter monthly income (Rs): ");
        double income = scanner.nextDouble();

        System.out.print("Enter credit score (300-900): ");
        int creditScore = scanner.nextInt();

        System.out.print("Any active loan default (true/false): ");
        boolean hasDefault = scanner.nextBoolean();

        // Compound decision criteria:
        // Must be 21-65, income >= 30000, credit score >= 750, and NO defaults!
        if ((age >= 21 && age <= 65) && income >= 30000.0 && creditScore >= 750 && !hasDefault) {
            System.out.println("ELIGIBILITY APPROVED: Qualified for Platinum Card.");
        } else {
            System.out.println("ELIGIBILITY DECLINED: Did not meet underwriting criteria.");
        }

        scanner.close();
    }
}

