import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int n = scanner.nextInt();
        if (n >= 10 && n <= 99) {
            System.out.println(n + " is a 2-digit positive number");
        } else {
            System.out.println(n + " is not a 2-digit positive number");
        }
        scanner.close();
    }
}

import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int day = scanner.nextInt();
        if (day == 6 || day == 7) {
            System.out.println("Weekend!");
        } else if (day >= 1 && day <= 5) {
            System.out.println("Weekday");
        } else {
            System.out.println("Invalid day");
        }
        scanner.close();
    }
}

import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int year = scanner.nextInt();
        if ((year % 4 == 0 && year % 100 != 0) || (year % 400 == 0)) {
            System.out.println(year + " is a Leap Year");
        } else {
            System.out.println(year + " is not a Leap Year");
        }
        scanner.close();
    }
}

import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int a1 = scanner.nextInt();
        int a2 = scanner.nextInt();
        int a3 = scanner.nextInt();
        if (a1 > 0 && a2 > 0 && a3 > 0 && (a1 + a2 + a3 == 180)) {
            System.out.println("Valid Triangle");
        } else {
            System.out.println("Invalid Angles");
        }
        scanner.close();
    }
}

import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int age = scanner.nextInt();
        boolean isStudent = scanner.nextBoolean();
        if (age >= 60 || isStudent) {
            System.out.println("Discount Applied");
        } else {
            System.out.println("Standard Fare");
        }
        scanner.close();
    }
}

import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        char ch = scanner.next().charAt(0);
        if ((ch >= 'a' && ch <= 'z') || (ch >= 'A' && ch <= 'Z')) {
            System.out.println(ch + " is an Alphabet");
        } else {
            System.out.println(ch + " is not an Alphabet");
        }
        scanner.close();
    }
}

import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        double gpa = scanner.nextDouble();
        double att = scanner.nextDouble();
        boolean warning = scanner.nextBoolean();
        if (gpa >= 3.75 && att >= 85.0 && !warning) {
            System.out.println("Scholarship Approved");
        } else {
            System.out.println("Scholarship Denied");
        }
        scanner.close();
    }
}

import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int h = scanner.nextInt();
        int m = scanner.nextInt();
        if (h >= 0 && h <= 23 && m >= 0 && m <= 59) {
            System.out.println("Valid 24-Hour Time");
        } else {
            System.out.println("Invalid Time Format");
        }
        scanner.close();
